WITH windows AS (SELECT 0 AS sample, 12124 AS pid, 8004570000000 AS start_ns, 8006316952874 AS end_ns UNION ALL SELECT 1 AS sample, 12124 AS pid, 8007240000000 AS start_ns, 8008937269457 AS end_ns UNION ALL SELECT 2 AS sample, 12124 AS pid, 8009920000000 AS start_ns, 8011567215291 AS end_ns UNION ALL SELECT 3 AS sample, 12124 AS pid, 8012510000000 AS start_ns, 8014172307082 AS end_ns UNION ALL SELECT 4 AS sample, 12124 AS pid, 8015010000000 AS start_ns, 8016676498208 AS end_ns UNION ALL SELECT 5 AS sample, 12124 AS pid, 8017480000000 AS start_ns, 8019129496916 AS end_ns UNION ALL SELECT 6 AS sample, 12124 AS pid, 8020000000000 AS start_ns, 8021664623542 AS end_ns UNION ALL SELECT 7 AS sample, 12124 AS pid, 8022570000000 AS start_ns, 8024227159541 AS end_ns UNION ALL SELECT 8 AS sample, 12124 AS pid, 8025140000000 AS start_ns, 8026821845208 AS end_ns UNION ALL SELECT 9 AS sample, 12124 AS pid, 8027710000000 AS start_ns, 8029501977208 AS end_ns UNION ALL SELECT 10 AS sample, 12124 AS pid, 8030410000000 AS start_ns, 8032070262082 AS end_ns UNION ALL SELECT 11 AS sample, 12124 AS pid, 8032810000000 AS start_ns, 8034461013041 AS end_ns UNION ALL SELECT 12 AS sample, 12124 AS pid, 8035290000000 AS start_ns, 8036935380666 AS end_ns UNION ALL SELECT 13 AS sample, 12124 AS pid, 8037940000000 AS start_ns, 8039596751125 AS end_ns UNION ALL SELECT 14 AS sample, 12124 AS pid, 8040540000000 AS start_ns, 8042225303457 AS end_ns UNION ALL SELECT 15 AS sample, 12124 AS pid, 8043070000000 AS start_ns, 8044721898500 AS end_ns UNION ALL SELECT 16 AS sample, 12124 AS pid, 8045520000000 AS start_ns, 8047172018458 AS end_ns UNION ALL SELECT 17 AS sample, 12124 AS pid, 8047960000000 AS start_ns, 8049610409791 AS end_ns UNION ALL SELECT 18 AS sample, 12124 AS pid, 8050470000000 AS start_ns, 8052121090582 AS end_ns UNION ALL SELECT 19 AS sample, 12124 AS pid, 8052870000000 AS start_ns, 8054521316875 AS end_ns UNION ALL SELECT 20 AS sample, 12124 AS pid, 8055360000000 AS start_ns, 8057025016959 AS end_ns UNION ALL SELECT 21 AS sample, 12124 AS pid, 8057930000000 AS start_ns, 8059586294542 AS end_ns UNION ALL SELECT 22 AS sample, 12124 AS pid, 8060540000000 AS start_ns, 8062198054999 AS end_ns UNION ALL SELECT 23 AS sample, 12124 AS pid, 8063030000000 AS start_ns, 8064689566375 AS end_ns UNION ALL SELECT 24 AS sample, 12124 AS pid, 8065500000000 AS start_ns, 8067151433166 AS end_ns UNION ALL SELECT 25 AS sample, 12124 AS pid, 8068160000000 AS start_ns, 8069834689334 AS end_ns UNION ALL SELECT 26 AS sample, 12124 AS pid, 8070730000000 AS start_ns, 8072393706541 AS end_ns UNION ALL SELECT 27 AS sample, 12124 AS pid, 8073310000000 AS start_ns, 8074959674042 AS end_ns UNION ALL SELECT 28 AS sample, 12124 AS pid, 8075810000000 AS start_ns, 8077465807125 AS end_ns UNION ALL SELECT 29 AS sample, 12124 AS pid, 8078340000000 AS start_ns, 8079988340083 AS end_ns UNION ALL SELECT 30 AS sample, 12124 AS pid, 8080760000000 AS start_ns, 8082410759083 AS end_ns UNION ALL SELECT 31 AS sample, 12124 AS pid, 8083350000000 AS start_ns, 8085007692292 AS end_ns UNION ALL SELECT 32 AS sample, 12124 AS pid, 8085860000000 AS start_ns, 8087513953459 AS end_ns UNION ALL SELECT 33 AS sample, 12124 AS pid, 8088730000000 AS start_ns, 8090385537333 AS end_ns UNION ALL SELECT 34 AS sample, 12124 AS pid, 8091170000000 AS start_ns, 8092837783459 AS end_ns UNION ALL SELECT 35 AS sample, 12124 AS pid, 8093740000000 AS start_ns, 8095402442417 AS end_ns)
SELECT w.sample, count(*) AS app_frame_records,
 sum(CASE WHEN a.jank_type LIKE '%App Deadline Missed%' THEN 1 ELSE 0 END) AS app_deadline_misses,
 sum(CASE WHEN a.jank_type != 'None' THEN 1 ELSE 0 END) AS all_jank_records,
 sum(CASE WHEN a.present_type = 'Dropped Frame' THEN 1 ELSE 0 END) AS dropped_frame_records,
 round(avg(a.dur)/1e6,2) AS mean_actual_frame_ms,
 round(max(a.dur)/1e6,2) AS max_actual_frame_ms,
 group_concat(a.dur) AS actual_durations_ns
FROM windows w JOIN process p ON p.pid=w.pid
JOIN actual_frame_timeline_slice a ON a.upid=p.upid
WHERE a.ts >= w.start_ns AND a.ts < w.end_ns AND a.dur > 0
GROUP BY w.sample ORDER BY w.sample